<?php
namespace Modules\BankingMicrofinanceTreasury\Services;
use Illuminate\Support\Facades\DB;use Modules\BankingMicrofinanceTreasury\Entities\TreasuryInterBranchTransfer;use Modules\BankingMicrofinanceTreasury\Entities\TreasuryVault;use Modules\BankingMicrofinanceTreasury\Entities\TreasuryVaultMovement;
class TreasuryPostingService{public function postTransfer(TreasuryInterBranchTransfer $transfer, ?int $userId=null): TreasuryInterBranchTransfer{return DB::transaction(function() use($transfer,$userId){$from=TreasuryVault::findOrFail($transfer->from_vault_id);$to=TreasuryVault::findOrFail($transfer->to_vault_id);if((float)$from->current_balance < (float)$transfer->amount){throw new \RuntimeException('Insufficient vault balance for treasury transfer.');}$from->current_balance -= $transfer->amount;$from->save();$to->current_balance += $transfer->amount;$to->save();TreasuryVaultMovement::create(['business_id'=>$transfer->business_id,'vault_id'=>$from->id,'movement_date'=>$transfer->transfer_date,'movement_type'=>'transfer_out','reference_no'=>$transfer->transfer_no,'credit'=>$transfer->amount,'balance_after'=>$from->current_balance,'created_by'=>$userId]);TreasuryVaultMovement::create(['business_id'=>$transfer->business_id,'vault_id'=>$to->id,'movement_date'=>$transfer->transfer_date,'movement_type'=>'transfer_in','reference_no'=>$transfer->transfer_no,'debit'=>$transfer->amount,'balance_after'=>$to->current_balance,'created_by'=>$userId]);$transfer->status='posted';$transfer->posted_by=$userId;$transfer->posted_at=now();$transfer->save();return $transfer;});}}
